set -euo pipefail
cd /home/ubuntu/apps/travel-planner
.venv/bin/python - <<'PY'
from pathlib import Path
import base64,json,hashlib
data=json.loads('{"rag/client/run_on_server.ps1": "", "docs/PLAN_CHAT_NL_INTAKE.md": "", "rag/eval/reports/plan_chat_deployment.json": "", "rag/eval/candidates/plan_chat_v1/manifest.json": ""}')
for n,b in data.items():
 p=Path(n);p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(base64.b64decode(b))
 assert hashlib.sha256(p.read_bytes()).digest()==hashlib.sha256(base64.b64decode(b)).digest()
print('Deployment report and docs synchronized')
PY
.venv/bin/python - <<'PY'
import requests
base='http://127.0.0.1:8100'
assert requests.get(base+'/health',timeout=10).json()['model_ready']
assert '/plan/chat' in requests.get(base+'/openapi.json',timeout=10).json()['paths']
print('Healthy private server; chat endpoint registered')
PY
